  ["92b74e7b45c66024"] = { "Inchinati al mio cospetto, insetto! Di certo senti il potere che ho su di te.", "." },
  ["92bb2dab981a2358"] = { "Bene, bene... Così Linken si è finalmente deciso a mandarmi la sua spada.", "." },
